package logstorage

import (
	"encoding/binary"
	"fmt"
	"math/bits"
	"sync"
	"unsafe"

	"github.com/cespare/xxhash/v2"

	"github.com/VictoriaMetrics/VictoriaMetrics/lib/bytesutil"
	"github.com/VictoriaMetrics/VictoriaMetrics/lib/logger"
	"github.com/VictoriaMetrics/VictoriaMetrics/lib/slicesutil"
)

// bloomFilterHashesCount is the number of different hashes to use for legacy bloom filter.
//
// The legacy bloom filter is used in parts with FormatVersion < partFormatSBBFVersion.
const bloomFilterHashesCount = 6

// bloomFilterTokenHashesCount is the number of hashes per token generated by appendTokensHashes() and appendHashesHashes().
//
// The first hash is the token hash itself, which is used by split block bloom filter.
// The remaining bloomFilterHashesCount hashes are used by legacy bloom filter.
const bloomFilterTokenHashesCount = 1 + bloomFilterHashesCount

// bloomFilterBitsPerItem is the number of bits to use per each token.
const bloomFilterBitsPerItem = 16

// sbbfBlockBits is the number of bits in a single split block bloom filter block.
const sbbfBlockBits = 256

// sbbfSalts are the salts for split block bloom filter. They are taken from the Parquet spec.
//
// See https://github.com/apache/parquet-format/blob/master/BloomFilter.md
var sbbfSalts = [8]uint32{0x47b6137b, 0x44974d91, 0x8824ad5b, 0xa2b7289d, 0x705495c7, 0x2df1424b, 0x9efc4947, 0x5c6bfb31}

// sbbfBlock is a single block of split block bloom filter.
//
// Every token sets exactly one bit in every word of a single block,
// so checking for a token touches a single cache line.
type sbbfBlock [8]uint32

// bloomFilterMarshalHashes appends marshaled bloom filter for hashes to dst and returns the result.
//
// hashes must contain unique token hashes generated by tokenizeHashes().
func bloomFilterMarshalHashes(dst []byte, hashes []uint64) []byte {
	bf := getBloomFilter()
	bf.mustInitHashes(hashes)
	dst = bf.marshal(dst)
	putBloomFilter(bf)
	return dst
}

// bloomFilter is either split block bloom filter (SBBF) or legacy bloom filter.
type bloomFilter struct {
	// blocks contains split block bloom filter blocks.
	blocks []sbbfBlock

	// bits contains legacy bloom filter bits. It is used only for parts with FormatVersion < partFormatSBBFVersion.
	//
	// The words are stored in their on-disk (big-endian) byte order, so unmarshaling is a plain copy.
	// Use legacyBloomFilterBitIndexXor for accessing individual bits.
	bits []uint64

	// isLegacy is set to true if bf contains legacy bloom filter.
	isLegacy bool
}

func (bf *bloomFilter) reset() {
	bf.blocks = bf.blocks[:0]
	bf.bits = bf.bits[:0]

	bf.isLegacy = false
}

// marshal appends marshaled bf to dst and returns the result.
func (bf *bloomFilter) marshal(dst []byte) []byte {
	if bf.isLegacy {
		logger.Panicf("BUG: legacy bloom filter cannot be marshaled")
	}
	for i := range bf.blocks {
		for _, w := range &bf.blocks[i] {
			dst = binary.LittleEndian.AppendUint32(dst, w)
		}
	}
	return dst
}

// unmarshal unmarshals bf from src, which has been written to the part with the given partFormatVersion.
func (bf *bloomFilter) unmarshal(src []byte, partFormatVersion uint) error {
	if partFormatVersion < partFormatSBBFVersion {
		return bf.unmarshalLegacy(src)
	}

	bf.reset()
	if len(src)%(sbbfBlockBits/8) != 0 {
		return fmt.Errorf("cannot unmarshal bloomFilter from src with size not multiple by %d; len(src)=%d", sbbfBlockBits/8, len(src))
	}
	blocks := slicesutil.SetLength(bf.blocks, len(src)/(sbbfBlockBits/8))
	if len(blocks) > 0 {
		// Copy src directly into blocks, since the filter is unmarshaled for every block scanned during search.
		copy(unsafe.Slice((*byte)(unsafe.Pointer(&blocks[0])), len(src)), src)
		if !isLittleEndian {
			for i := range blocks {
				b := &blocks[i]
				for j := range b {
					b[j] = bits.ReverseBytes32(b[j])
				}
			}
		}
	}
	bf.blocks = blocks
	return nil
}

var isLittleEndian = binary.NativeEndian.Uint16([]byte{1, 0}) == 1

func (bf *bloomFilter) unmarshalLegacy(src []byte) error {
	bf.reset()
	bf.isLegacy = true
	if len(src)%8 != 0 {
		return fmt.Errorf("cannot unmarshal legacy bloomFilter from src with size not multiple by 8; len(src)=%d", len(src))
	}
	bits := slicesutil.SetLength(bf.bits, len(src)/8)
	if len(bits) > 0 {
		copy(unsafe.Slice((*byte)(unsafe.Pointer(&bits[0])), len(src)), src)
	}
	bf.bits = bits
	return nil
}

// legacyBloomFilterBitIndexXor is 56 on little-endian architectures, where bloomFilter.bits words are stored with swapped bytes, and 0 otherwise.
//
// Swapping the bytes of a word maps its bit j to the bit j^56.
var legacyBloomFilterBitIndexXor = func() uint64 {
	if isLittleEndian {
		return 56
	}
	return 0
}()

// mustInitHashes initializes bf with the given unique token hashes
func (bf *bloomFilter) mustInitHashes(hashes []uint64) {
	bitsCount := len(hashes) * bloomFilterBitsPerItem
	blocksCount := (bitsCount + sbbfBlockBits - 1) / sbbfBlockBits
	blocks := slicesutil.SetLength(bf.blocks, blocksCount)
	clear(blocks)
	for _, h := range hashes {
		b := &blocks[sbbfBlockIdx(h, len(blocks))]
		key := uint32(h)
		for i := range b {
			b[i] |= 1 << ((key * sbbfSalts[i]) >> 27)
		}
	}
	bf.blocks = blocks
	bf.isLegacy = false
}

// sbbfBlockIdx returns the index of the block for the token hash h in the filter with blocksCount blocks.
func sbbfBlockIdx(h uint64, blocksCount int) uint64 {
	return ((h >> 32) * uint64(blocksCount)) >> 32
}

// appendTokensHashes appends hashes for the given tokens to dst and returns the result.
//
// bloomFilterTokenHashesCount hashes are appended per every token.
//
// The appended hashes can be then passed to bloomFilter.containsAll().
func appendTokensHashes(dst []uint64, tokens []string) []uint64 {
	dstLen := len(dst)
	hashesCount := len(tokens) * bloomFilterTokenHashesCount

	dst = slicesutil.SetLength(dst, dstLen+hashesCount)
	dst = dst[:dstLen]

	for _, token := range tokens {
		h := xxhash.Sum64(bytesutil.ToUnsafeBytes(token))
		dst = appendTokenHashes(dst, h)
	}
	return dst
}

// appendHashesHashes appends hashes for the given hashes to dst and returns the result.
//
// The hashes must be generated from tokens by tokenizeHashes().
// See also appendTokensHashes().
//
// The appended hashes can be then passed to bloomFilter.containsAll().
func appendHashesHashes(dst, hashes []uint64) []uint64 {
	dstLen := len(dst)
	hashesCount := len(hashes) * bloomFilterTokenHashesCount

	dst = slicesutil.SetLength(dst, dstLen+hashesCount)
	dst = dst[:dstLen]

	for _, h := range hashes {
		dst = appendTokenHashes(dst, h)
	}
	return dst
}

// appendTokenHashes appends bloomFilterTokenHashesCount hashes for the token hash h to dst and returns the result.
func appendTokenHashes(dst []uint64, h uint64) []uint64 {
	dst = append(dst, h)

	var buf [8]byte
	hp := (*uint64)(unsafe.Pointer(&buf[0]))
	*hp = h
	for range bloomFilterHashesCount {
		dst = append(dst, xxhash.Sum64(buf[:]))
		(*hp)++
	}
	return dst
}

// containsAll returns true if bf contains all the given tokens hashes generated by appendTokensHashes or appendHashesHashes
func (bf *bloomFilter) containsAll(hashes []uint64) bool {
	if bf.isLegacy {
		return bf.containsAllLegacy(hashes)
	}

	blocks := bf.blocks
	if len(blocks) == 0 {
		return true
	}
	for i := 0; i < len(hashes); i += bloomFilterTokenHashesCount {
		h := hashes[i]
		b := &blocks[sbbfBlockIdx(h, len(blocks))]
		key := uint32(h)
		for j := range b {
			if b[j]&(1<<((key*sbbfSalts[j])>>27)) == 0 {
				// The token is missing
				return false
			}
		}
	}
	return true
}

func (bf *bloomFilter) containsAllLegacy(hashes []uint64) bool {
	bits := bf.bits
	if len(bits) == 0 {
		return true
	}
	maxBits := uint64(len(bits)) * 64
	bitIndexXor := legacyBloomFilterBitIndexXor
	for i, h := range hashes {
		if i%bloomFilterTokenHashesCount == 0 {
			// Skip the token hash, since it is used only by split block bloom filter
			continue
		}
		idx := h % maxBits
		mask := uint64(1) << ((idx % 64) ^ bitIndexXor)
		w := bits[idx/64]
		if (w & mask) == 0 {
			// The token is missing
			return false
		}
	}
	return true
}

func getBloomFilter() *bloomFilter {
	v := bloomFilterPool.Get()
	if v == nil {
		return &bloomFilter{}
	}
	return v.(*bloomFilter)
}

func putBloomFilter(bf *bloomFilter) {
	bf.reset()
	bloomFilterPool.Put(bf)
}

var bloomFilterPool sync.Pool
